script:
--Config ig
local G_D = true -- Turn this to false if u dont want 0.2 domain
--
local ReplicatedStorage = game: GetService("ReplicatedStorage")
local Players = game: GetService("Players")
local RunService = game: GetService("RunService")
local player1 = game.Players.LocalPlayer
local playerName = player1.Name

local args = {
    [1] = "106882572101661"
}
if G_D == true then
    game: GetService("ReplicatedStorage").GetCoil: FireServer(unpack(args))
end
--0.2 Domain

local player = Players.LocalPlayer
local TOOL_NAME = "Reversal Red" 

local character = player.Character or player.CharacterAdded: Wait()
local backpack = player: WaitForChild("Backpack")

local tool = backpack: FindFirstChild(TOOL_NAME)
if not tool then
    tool = backpack: WaitForChild(TOOL_NAME,  5)
end

if tool and tool: IsA("Tool") then
    tool.Parent = character
else
    print("You did not equip Gojo,  please equip Gojo for the script to work,  when you do,  execute this script again.")
end

--
local function destroyScript()
    local mobsFolder = workspace: FindFirstChild("Mobs")
    if not mobsFolder then return end

    local playerMob = mobsFolder: FindFirstChild(playerName)
    if not playerMob then return end

    local reversalRed = playerMob: FindFirstChild("Reversal Red")
    if not reversalRed then return end

    local targetScript = reversalRed: FindFirstChild("LocalScript")
    if targetScript and targetScript: IsA("LocalScript") then
        pcall(function()
            targetScript: Destroy()
        end)
    end
end

destroyScript()

local cd = false
local debounce = true
local guiNames = {"Character",  "Gamepass"}

local function setGuisEnabled(enabled)
    local playerGui = player: FindFirstChild("PlayerGui")
    if not playerGui then return end

    for _,  name in ipairs(guiNames) do
        local gui = playerGui: FindFirstChild(name)
        if gui and gui: IsA("ScreenGui") then
            gui.Enabled = enabled
        end
    end
end

local function Updatename()
    local air = character: FindFirstChild("Air")
    if air and air.Value == true and cd == false then
        tool.Name = "2000% Red"
    elseif air and not air.Value and cd == false then 
        tool.Name = "Reversal Red"
    end
end

-- Wait for tool to exist in workspace
local toolInWorkspace = nil
repeat
    local mobsFolder = workspace: FindFirstChild("Mobs")
    if mobsFolder then
        local playerMob = mobsFolder: FindFirstChild(player.Name)
        if playerMob then
            toolInWorkspace = playerMob: FindFirstChild("Reversal Red")
        end
    end
    if not toolInWorkspace then task.wait() end
until toolInWorkspace

-- Connect once,  avoid redundant checks
if toolInWorkspace then
    RunService.RenderStepped: Connect(Updatename)
end

local dialogueModule = nil
pcall(function()
    dialogueModule = require(ReplicatedStorage: WaitForChild("TekrinnDialogue"))
end)

if toolInWorkspace and toolInWorkspace: IsA("Tool") then
    toolInWorkspace.Activated: Connect(function()
        if cd or not debounce then return end

        local debounceObj = character: FindFirstChild("Debounce")
        if not debounceObj or not debounceObj.Value then return end

        local air = character: FindFirstChild("Air")
        local isAir = air and air.Value

        cd = true
        debounce = false
        setGuisEnabled(false)

        local duration = isAir and 10 or 5

        if isAir then
            for i = 1,  21 do
                ReplicatedStorage.Remotes.Red2: FireServer()
            end
        else
            for z = 1,  11 do
                ReplicatedStorage.Remotes.Red: FireServer()
            end
        end

        task.spawn(function()
            local customGui = player.PlayerGui: FindFirstChild(player.Name.."CUSTOM_DIALOGUE")
            if customGui then customGui: Destroy() end

            if dialogueModule then
                if isAir then
                    task.wait(1.75)
                    dialogueModule.Speak(player,  {
                        {
                            Text = "Ultra Technique Reversal...";
                            Color = ColorSequence.new(Color3.fromRGB(255,  255,  255));
                            TextStrokeColor = Color3.fromRGB(0,  0,  0);
                            Bold = false;
                            Italic = false;
                            TypeSpeed = 0.05;
                            Shake = {
                                Enabled = false;
                                Intensity = 0;
                                Lifetime = 0;
                            };
                        }
                    })
                    task.wait(3.75)
                    dialogueModule.Speak(player,  {
                        {
                            Text = "2000% Red.";
                            Color = ColorSequence.new({ColorSequenceKeypoint.new(0,  Color3.fromRGB(200,  0,  0)),  ColorSequenceKeypoint.new(1,  Color3.fromRGB(255,  80,  80))});
                            TextStrokeColor = Color3.new(0,  0,  0);
                            Bold = true;
                            Italic = false;
                            TypeSpeed = 0.05;
                            Shake = {
                                Enabled = true;
                                Intensity = 3;
                                Lifetime = 1;
                            };
                        }
                    })
                else
                    task.wait(0.5)
                    dialogueModule.Speak(player,  {
                        {
                            Text = "Reversal Cursed Technique:  ";
                            Color = ColorSequence.new(Color3.fromRGB(255,  255,  255));
                            TextStrokeColor = Color3.new(0,  0,  0);
                            Bold = false;
                            Italic = false;
                            TypeSpeed = 0.05;
                            Shake = {
                                Enabled = false;
                                Intensity = 0;
                                Lifetime = 0;
                            };
                        },    
                        {
                            Text = "Amplified 1000% Red";
                            Color = ColorSequence.new({ColorSequenceKeypoint.new(0,  Color3.fromRGB(200,  0,  0)),  ColorSequenceKeypoint.new(1,  Color3.fromRGB(255,  80,  80))});
                            TextStrokeColor = Color3.new(0,  0,  0);
                            Bold = true;
                            Italic = false;
                            TypeSpeed = 0.05;
                            Shake = {
                                Enabled = true;
                                Intensity = 3;
                                Lifetime = 1;
                            };
                        }
                    })
                end
            end
        end)

        local startTime = tick()
        task.spawn(function()
            while tick() - startTime < duration do
                if toolInWorkspace and toolInWorkspace.Parent then
                    local timeLeft = duration - (tick() - startTime)
                    if timeLeft > 0 then
                        toolInWorkspace.Name = string.format("%.2fs",  timeLeft)
                    end
                else
                    break
                end
                task.wait(0.05)
            end

            -- Restore normal names and re-enable tool
            debounce = true
            setGuisEnabled(true)
            cd = false
            if toolInWorkspace and toolInWorkspace.Parent then
                Updatename()
            end
        end)
    end)
end
